<script lang="ts">import { onMount } from 'svelte'; import { api } from '$lib/api'; import StudentShell from '$lib/components/StudentShell.svelte'; import { apiError, requireStudent, type StudentSession } from '$lib/student-session'; let session: StudentSession | null = null; let items: any[] = []; let error = ''; onMount(async () => { session = await requireStudent(); if (!session) return; try { items = await api<any[]>('/api/student/news'); } catch (e) { error = apiError(e); } });</script>
{#if session}<StudentShell {session} active="news"><section class="student-heading"><span class="student-eyebrow">FROM THE DOJO</span><h1>NEWS</h1><p>Published updates and notes from Task Karate.</p></section>{#if error}<div class="error">{error}</div>{:else if items.length === 0}<section class="student-panel empty-panel"><h2>No published news yet.</h2><p>New dojo updates will appear here when they are published.</p></section>{:else}<div class="news-stack">{#each items as item}<article class="student-panel news-card"><span class="student-eyebrow">{new Date(item.publishedAt).toLocaleDateString()}</span><h2>{item.title}</h2><p>{item.body}</p></article>{/each}</div>{/if}</StudentShell>{/if}
